-- MozTransport: base de dados PostgreSQL (esquema + dados)
-- Importar:  psql "$DATABASE_URL" -f moztransport-postgres.sql
SET client_encoding = 'UTF8';
BEGIN;

CREATE TABLE "transportadoras" (
  "id" bigint generated by default as identity primary key,
  "nome" varchar(255) not null,
  "nuit" varchar(255),
  "contacto" varchar(255),
  "endereco" varchar(255),
  "descricao" varchar(255),
  "estado" varchar(255) default 'activa' not null,
  "created_at" timestamp(0) without time zone,
  "updated_at" timestamp(0) without time zone
);
CREATE TABLE "autocarros" (
  "id" bigint generated by default as identity primary key,
  "matricula" varchar(255) not null,
  "modelo" varchar(255),
  "capacidade_total" bigint default 44 not null,
  "transportadora_id" bigint not null,
  "estado" varchar(255) default 'activo' not null,
  "created_at" timestamp(0) without time zone,
  "updated_at" timestamp(0) without time zone,
  "ano" bigint,
  "livrete_caminho" varchar(255),
  "livrete_nome" varchar(255),
  "livrete_em" timestamp(0) without time zone,
  foreign key ("transportadora_id") references "transportadoras" ("id") on delete cascade
);
CREATE TABLE "assentos" (
  "id" bigint generated by default as identity primary key,
  "numero" bigint not null,
  "tipo" varchar(255) default 'janela' not null,
  "autocarro_id" bigint not null,
  foreign key ("autocarro_id") references "autocarros" ("id") on delete cascade
);
CREATE TABLE "utilizadores" (
  "id" bigint generated by default as identity primary key,
  "nome" varchar(255) not null,
  "email" varchar(255) not null,
  "telefone" varchar(255),
  "documento" varchar(255),
  "senha" varchar(255) not null,
  "perfil" varchar(255) default 'passageiro' not null,
  "transportadora_id" bigint,
  "agencia" varchar(255),
  "estado" varchar(255) default 'activo' not null,
  "tentativas_falhadas" bigint default 0 not null,
  "bloqueado_ate" timestamp(0) without time zone,
  "notificacoes" boolean default true not null,
  "idioma" varchar(255) default 'pt' not null,
  "remember_token" varchar(255),
  "created_at" timestamp(0) without time zone,
  "updated_at" timestamp(0) without time zone,
  foreign key ("transportadora_id") references "transportadoras" ("id") on delete set null
);
CREATE TABLE "auditoria" (
  "id" bigint generated by default as identity primary key,
  "utilizador_id" bigint,
  "utilizador_nome" varchar(255),
  "acao" varchar(255) not null,
  "detalhe" varchar(255),
  "cor" varchar(255) default 'verde' not null,
  "ip" varchar(255),
  "created_at" timestamp(0) without time zone default CURRENT_TIMESTAMP not null,
  foreign key ("utilizador_id") references "utilizadores" ("id") on delete set null
);
CREATE TABLE "motoristas" (
  "id" bigint generated by default as identity primary key,
  "nome" varchar(255) not null,
  "telefone" varchar(255),
  "documento" varchar(255),
  "carta_numero" varchar(255) not null,
  "carta_categoria" varchar(255),
  "carta_validade" date,
  "estado" varchar(255) default 'activo' not null,
  "transportadora_id" bigint not null,
  "created_at" timestamp(0) without time zone,
  "updated_at" timestamp(0) without time zone,
  foreign key ("transportadora_id") references "transportadoras" ("id") on delete cascade
);
CREATE TABLE "rotas" (
  "id" bigint generated by default as identity primary key,
  "origem" varchar(255) not null,
  "destino" varchar(255) not null,
  "distancia_km" bigint default 0 not null,
  "duracao_minutos" bigint default 0 not null,
  "preco_base" bigint default 0 not null,
  "transportadora_id" bigint not null,
  "estado" varchar(255) default 'activa' not null,
  "created_at" timestamp(0) without time zone,
  "updated_at" timestamp(0) without time zone,
  foreign key ("transportadora_id") references "transportadoras" ("id") on delete cascade
);
CREATE TABLE "viagens" (
  "id" bigint generated by default as identity primary key,
  "data" date not null,
  "hora_partida" time(0) without time zone not null,
  "preco" bigint not null,
  "classe" varchar(255) default 'Executivo' not null,
  "estado" varchar(255) default 'agendada' not null,
  "rota_id" bigint not null,
  "autocarro_id" bigint not null,
  "cobrador_id" bigint,
  "created_at" timestamp(0) without time zone,
  "updated_at" timestamp(0) without time zone,
  "motorista_id" bigint,
  foreign key ("motorista_id") references "motoristas" ("id") on delete set null,
  foreign key ("rota_id") references "rotas" ("id") on delete cascade,
  foreign key ("autocarro_id") references "autocarros" ("id") on delete cascade,
  foreign key ("cobrador_id") references "utilizadores" ("id") on delete set null
);
CREATE TABLE "reservas" (
  "id" bigint generated by default as identity primary key,
  "grupo" varchar(255),
  "passageiro_id" bigint,
  "bilheteiro_id" bigint,
  "viagem_id" bigint not null,
  "assento_id" bigint not null,
  "nome_passageiro" varchar(255) not null,
  "documento" varchar(255),
  "telefone" varchar(255),
  "estado" varchar(255) default 'pendente' not null,
  "ativa" smallint,
  "expira_em" timestamp(0) without time zone,
  "data_reserva" timestamp(0) without time zone default CURRENT_TIMESTAMP not null,
  "created_at" timestamp(0) without time zone,
  "updated_at" timestamp(0) without time zone,
  foreign key ("assento_id") references "assentos" ("id") on delete cascade,
  foreign key ("viagem_id") references "viagens" ("id") on delete cascade,
  foreign key ("bilheteiro_id") references "utilizadores" ("id") on delete set null,
  foreign key ("passageiro_id") references "utilizadores" ("id") on delete set null
);
CREATE TABLE "bilhetes" (
  "id" bigint generated by default as identity primary key,
  "reserva_id" bigint not null,
  "codigo_qr" varchar(255) not null,
  "data_emissao" timestamp(0) without time zone default CURRENT_TIMESTAMP not null,
  "estado" varchar(255) default 'valido' not null,
  "validado_em" timestamp(0) without time zone,
  "validado_por" bigint,
  "created_at" timestamp(0) without time zone,
  "updated_at" timestamp(0) without time zone,
  foreign key ("validado_por") references "utilizadores" ("id") on delete set null,
  foreign key ("reserva_id") references "reservas" ("id") on delete cascade
);
CREATE TABLE "cache" (
  "key" varchar(255) not null,
  "value" text not null,
  "expiration" bigint not null,
  primary key ("key")
);
CREATE TABLE "cache_locks" (
  "key" varchar(255) not null,
  "owner" varchar(255) not null,
  "expiration" bigint not null,
  primary key ("key")
);
CREATE TABLE "codigos_recuperacao" (
  "id" bigint generated by default as identity primary key,
  "email" varchar(255) not null,
  "codigo_hash" varchar(255) not null,
  "expira_em" timestamp(0) without time zone not null,
  "usado_em" timestamp(0) without time zone,
  "created_at" timestamp(0) without time zone,
  "updated_at" timestamp(0) without time zone
);
CREATE TABLE "definicoes" (
  "chave" varchar(255) not null,
  "valor" varchar(255) not null,
  primary key ("chave")
);
CREATE TABLE "failed_jobs" (
  "id" bigint generated by default as identity primary key,
  "uuid" varchar(255) not null,
  "connection" varchar(255) not null,
  "queue" varchar(255) not null,
  "payload" text not null,
  "exception" text not null,
  "failed_at" timestamp(0) without time zone default CURRENT_TIMESTAMP not null
);
CREATE TABLE "job_batches" (
  "id" varchar(255) not null,
  "name" varchar(255) not null,
  "total_jobs" bigint not null,
  "pending_jobs" bigint not null,
  "failed_jobs" bigint not null,
  "failed_job_ids" text not null,
  "options" text,
  "cancelled_at" bigint,
  "created_at" bigint not null,
  "finished_at" bigint
);
CREATE TABLE "jobs" (
  "id" bigint generated by default as identity primary key,
  "queue" varchar(255) not null,
  "payload" text not null,
  "attempts" bigint not null,
  "reserved_at" bigint,
  "available_at" bigint not null,
  "created_at" bigint not null
);
CREATE TABLE "migrations" (
  "id" bigint generated by default as identity primary key,
  "migration" varchar(255) not null,
  "batch" bigint not null
);
CREATE TABLE "pagamentos" (
  "id" bigint generated by default as identity primary key,
  "reserva_id" bigint not null,
  "valor" bigint not null,
  "metodo" varchar(255) not null,
  "estado" varchar(255) default 'pago' not null,
  "data_pagamento" timestamp(0) without time zone,
  "referencia_transacao" varchar(255),
  "codigo_erro" varchar(255),
  "created_at" timestamp(0) without time zone,
  "updated_at" timestamp(0) without time zone,
  foreign key ("reserva_id") references "reservas" ("id") on delete cascade
);
CREATE TABLE "permissoes" (
  "id" bigint generated by default as identity primary key,
  "perfil" varchar(255) not null,
  "chave" varchar(255) not null,
  "ativo" boolean default false not null
);

CREATE INDEX "cache_expiration_index" ON "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" ON "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" ON "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" ON "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" ON "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "utilizadores_email_unique" ON "utilizadores" ("email");
CREATE INDEX "utilizadores_perfil_index" ON "utilizadores" ("perfil");
CREATE UNIQUE INDEX "autocarros_matricula_unique" ON "autocarros" ("matricula");
CREATE UNIQUE INDEX "assentos_autocarro_id_numero_unique" ON "assentos" ("autocarro_id", "numero");
CREATE INDEX "rotas_origem_destino_index" ON "rotas" ("origem", "destino");
CREATE UNIQUE INDEX "reservas_lugar_unico" ON "reservas" ("viagem_id", "assento_id", "ativa");
CREATE INDEX "reservas_grupo_index" ON "reservas" ("grupo");
CREATE INDEX "reservas_estado_index" ON "reservas" ("estado");
CREATE INDEX "pagamentos_data_pagamento_index" ON "pagamentos" ("data_pagamento");
CREATE UNIQUE INDEX "bilhetes_codigo_qr_unique" ON "bilhetes" ("codigo_qr");
CREATE INDEX "auditoria_created_at_index" ON "auditoria" ("created_at");
CREATE UNIQUE INDEX "permissoes_perfil_chave_unique" ON "permissoes" ("perfil", "chave");
CREATE INDEX "codigos_recuperacao_email_index" ON "codigos_recuperacao" ("email");
CREATE INDEX "viagens_data_index" ON "viagens" ("data");
















SELECT setval(pg_get_serial_sequence('"transportadoras"','id'), COALESCE((SELECT MAX(id) FROM "transportadoras"),1), (SELECT MAX(id) FROM "transportadoras") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"autocarros"','id'), COALESCE((SELECT MAX(id) FROM "autocarros"),1), (SELECT MAX(id) FROM "autocarros") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"assentos"','id'), COALESCE((SELECT MAX(id) FROM "assentos"),1), (SELECT MAX(id) FROM "assentos") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"utilizadores"','id'), COALESCE((SELECT MAX(id) FROM "utilizadores"),1), (SELECT MAX(id) FROM "utilizadores") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"auditoria"','id'), COALESCE((SELECT MAX(id) FROM "auditoria"),1), (SELECT MAX(id) FROM "auditoria") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"motoristas"','id'), COALESCE((SELECT MAX(id) FROM "motoristas"),1), (SELECT MAX(id) FROM "motoristas") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"rotas"','id'), COALESCE((SELECT MAX(id) FROM "rotas"),1), (SELECT MAX(id) FROM "rotas") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"viagens"','id'), COALESCE((SELECT MAX(id) FROM "viagens"),1), (SELECT MAX(id) FROM "viagens") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"reservas"','id'), COALESCE((SELECT MAX(id) FROM "reservas"),1), (SELECT MAX(id) FROM "reservas") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"bilhetes"','id'), COALESCE((SELECT MAX(id) FROM "bilhetes"),1), (SELECT MAX(id) FROM "bilhetes") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"codigos_recuperacao"','id'), COALESCE((SELECT MAX(id) FROM "codigos_recuperacao"),1), (SELECT MAX(id) FROM "codigos_recuperacao") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"failed_jobs"','id'), COALESCE((SELECT MAX(id) FROM "failed_jobs"),1), (SELECT MAX(id) FROM "failed_jobs") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"jobs"','id'), COALESCE((SELECT MAX(id) FROM "jobs"),1), (SELECT MAX(id) FROM "jobs") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"migrations"','id'), COALESCE((SELECT MAX(id) FROM "migrations"),1), (SELECT MAX(id) FROM "migrations") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"pagamentos"','id'), COALESCE((SELECT MAX(id) FROM "pagamentos"),1), (SELECT MAX(id) FROM "pagamentos") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('"permissoes"','id'), COALESCE((SELECT MAX(id) FROM "permissoes"),1), (SELECT MAX(id) FROM "permissoes") IS NOT NULL);

COMMIT;
